export {};
type Settings = { historyEnabled: boolean; auditEnabled: boolean; metricsEnabled: boolean; retentionDays: number; budgetMB: number; sampleSeconds: number };
type Server = { name: string; interface: string; address: string; endpoint: string; port: number; dns: string; allowedIPs: string; mtu: number; publicKey: string };
type Peer = { id: string; name: string; address: string; publicKey: string; enabled: boolean; createdAt: string; expiresAt: string | null; hasConfig: boolean; status: string; endpoint: string; lastHandshake: string | null; rxBytes: number; txBytes: number; rxRate: number; txRate: number };
type Point = { time: string; rx: number; tx: number; active: number };
type Event = { id: string; time: string; level: string; action: string; detail: string };
type Resources = { appMemory: number; goroutines: number; hostMemoryTotal: number; hostMemoryUsed: number; diskFree: number; diskTotal: number; hostCPU: number; controlBytes: number; telemetryBytes: number };
type Snapshot = { mode: string; version: string; startedAt: string; updatedAt: string; server: Server; settings: Settings; peers: Peer[]; points: Point[]; events: Event[]; resources: Resources; warnings: string[]; interfaceUp: boolean; historyPaused: boolean };
type Session = { authenticated: boolean; setupRequired: boolean; mode: string; user: string; csrf: string };
type View = 'overview' | 'peers' | 'activity' | 'storage' | 'settings';

const app = document.querySelector<HTMLDivElement>('#app')!;
const modal = document.querySelector<HTMLDialogElement>('#modal')!;
const paths: Record<string, string> = {
  grid: '<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',
  devices: '<rect x="3" y="4" width="14" height="11" rx="2"/><path d="M7 20h6m-3-5v5"/><rect x="17" y="10" width="5" height="11" rx="1"/>',
  pulse: '<path d="M2 12h5l3-8 4 16 3-8h5"/>',
  storage: '<ellipse cx="12" cy="5" rx="8" ry="3"/><path d="M4 5v7c0 1.7 3.6 3 8 3s8-1.3 8-3V5M4 12v7c0 1.7 3.6 3 8 3s8-1.3 8-3v-7"/>',
  settings: '<path d="M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8Z"/><path d="m9 3-1 3-3 1-2 3 2 2-1 4 3 2 3-1 2 4 3-1 1-3 4-1 1-3-3-2 1-3-3-2-3 1Z"/>',
  plus: '<path d="M12 5v14M5 12h14"/>',
  arrow: '<path d="M5 12h14m-5-5 5 5-5 5"/>',
  down: '<path d="M12 4v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',
  up: '<path d="M12 20V4m-6 6 6-6 6 6"/>',
  chevron: '<path d="m9 5 7 7-7 7"/>',
  search: '<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',
  shield: '<path d="m12 3 8 3v6c0 5-8 9-8 9S4 17 4 12V6l8-3Z"/><path d="m8 12 3 3 5-6"/>',
  server: '<rect x="3" y="3" width="18" height="7" rx="2"/><rect x="3" y="14" width="18" height="7" rx="2"/><path d="M7 6.5h.1M7 17.5h.1M16 6.5h2M16 17.5h2"/>',
  leaf: '<path d="M20 3c-9-1-17 4-16 11 1 8 15 9 16-11ZM5 19 16 8"/>',
  clock: '<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
  close: '<path d="m6 6 12 12M6 18 18 6"/>',
  check: '<path d="m5 12 4 4L19 6"/>',
  dots: '<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',
  qr: '<rect x="3" y="3" width="6" height="6"/><rect x="15" y="3" width="6" height="6"/><rect x="3" y="15" width="6" height="6"/><path d="M15 15h3v3h3v3h-6v-3m6-3v-3M12 3v6m-9 3h6m3 3v6"/>',
  pause: '<path d="M8 5v14M16 5v14"/>',
  play: '<path d="m8 4 12 8-12 8V4Z"/>',
  trash: '<path d="M3 6h18M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7m4-7v7"/>',
  info: '<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v.1"/>',
  copy: '<rect x="8" y="8" width="12" height="13" rx="2"/><path d="M15 8V3H3v12h5"/>',
  bell: '<path d="M5 10a7 7 0 0 1 14 0v5l2 3H3l2-3v-5Zm5 11h4"/>',
  globe: '<circle cx="12" cy="12" r="9"/><ellipse cx="12" cy="12" rx="4" ry="9"/><path d="M3 12h18"/>',
  logout: '<path d="M9 4H4v16h5m5-12 4 4-4 4M8 12h12"/>',
  menu: '<path d="M4 6h16M4 12h16M4 18h16"/>',
  lock: '<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3m-4 5v2"/>',
  upload: '<path d="M12 16V3m-5 5 5-5 5 5M4 16v5h16v-5"/>',
};
function icon(name: string, cls = ''): string { return `<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name] ?? paths.info}</svg>`; }
function esc(v: unknown): string { return String(v ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]!); }
function bytes(v: number, decimals = 1): string { if (!Number.isFinite(v) || v <= 0) return '0 B'; const i = Math.min(4, Math.floor(Math.log(v) / Math.log(1024))); return `${(v / 1024 ** i).toLocaleString('tr-TR', { maximumFractionDigits: decimals })} ${['B', 'KB', 'MB', 'GB', 'TB'][i]}`; }
function rate(v: number): string { if (v < 125000) return `${(v * 8 / 1000).toLocaleString('tr-TR', { maximumFractionDigits: 1 })} Kbps`; return `${(v * 8 / 1e6).toLocaleString('tr-TR', { maximumFractionDigits: 2 })} Mbps`; }
function ago(v: string | null): string { if (!v) return 'Henüz yok'; const sec = Math.max(0, (Date.now() - new Date(v).getTime()) / 1000); if (sec < 60) return `${Math.floor(sec)} sn önce`; if (sec < 3600) return `${Math.floor(sec / 60)} dk önce`; if (sec < 86400) return `${Math.floor(sec / 3600)} sa önce`; return `${Math.floor(sec / 86400)} gün önce`; }
function time(v: string): string { return new Date(v).toLocaleTimeString('tr-TR', { hour: '2-digit', minute: '2-digit' }); }
function date(v: string): string { return new Date(v).toLocaleDateString('tr-TR', { day: 'numeric', month: 'short' }); }
function status(p: Peer): string { return p.status === 'active' ? '<span class="badge green"><i></i>Aktif</span>' : p.status === 'disabled' ? '<span class="badge muted"><i></i>Devre dışı</span>' : '<span class="badge amber"><i></i>Beklemede</span>'; }

let session: Session;
let state: Snapshot;
let view: View = 'overview';
let query = '';
let peerFilter = 'all';
let chartMode = 'live';
let history: Point[] = [];
let poll: ReturnType<typeof setInterval> | undefined;
let refreshBusy = false;
let failures = 0;
let toastTimer: ReturnType<typeof setTimeout>;
let qrBlob = '';

async function api<T = unknown>(path: string, method = 'GET', body?: unknown): Promise<T> {
  const response = await fetch(path, { method, credentials: 'same-origin', headers: { ...(body !== undefined ? { 'Content-Type': 'application/json' } : {}), ...(session?.csrf ? { 'X-CSRF-Token': session.csrf } : {}) }, body: body === undefined ? undefined : JSON.stringify(body) });
  if (!response.ok) { const error = await response.json().catch(() => ({ error: `İstek tamamlanamadı (${response.status})` })); if (response.status === 401 && session) { clearInterval(poll); session.authenticated = false; renderAuth(); } throw new Error(error.error ?? 'İstek tamamlanamadı'); }
  return await response.json() as T;
}
function toast(message: string, error = false): void { const el = document.querySelector<HTMLDivElement>('#toast')!; el.textContent = message; el.className = `visible ${error ? 'error' : ''}`; clearTimeout(toastTimer); toastTimer = setTimeout(() => { el.className = ''; }, 4500); }
async function action(fn: () => Promise<void>): Promise<void> { try { await fn(); } catch (err) { toast(err instanceof Error ? err.message : 'İşlem tamamlanamadı', true); } }
async function refresh(force = false): Promise<void> {
  if (refreshBusy || (document.hidden && !force)) return; refreshBusy = true;
  try {
    state = await api<Snapshot>('/api/snapshot'); failures = 0;
    if (!document.querySelector('.shell')) shell();
    const active = document.activeElement;
    if (force || !modal.open && !(active instanceof HTMLInputElement || active instanceof HTMLTextAreaElement || active instanceof HTMLSelectElement) && ['overview', 'peers', 'activity'].includes(view)) renderMain();
    updateChrome();
  } catch (error) { failures++; updateChrome(); if (force) throw error; } finally { refreshBusy = false; }
}
function navigate(next: View): void { view = next; query = ''; chartMode = 'live'; location.hash = next; renderMain(); updateChrome(); document.querySelector('.sidebar')?.classList.remove('mobile-open'); document.querySelector('#mobile-menu')?.setAttribute('aria-expanded','false'); window.scrollTo(0, 0); }

function shell(): void {
  app.innerHTML = `<div class="shell"><aside class="sidebar"><a href="#overview" class="brand" aria-label="WireGuard Simple ana sayfa"><span class="brand-icon"><svg viewBox="0 0 40 40" fill="none"><path d="m5 12 7 17 8-13 8 13 7-17" stroke="currentColor" stroke-width="3.5" stroke-linecap="round" stroke-linejoin="round"/></svg></span><span>wireguard<span class="brand-sub">simple</span></span><span class="version-tag">α</span></a><div class="workspace"><span class="workspace-symbol">S</span><div><strong>Çalışma alanım</strong><small>Bağımsız ağ konsolu</small></div>${icon('chevron')}</div><div class="nav-label">YÖNETİM</div><nav aria-label="Ana menü">${(['overview', 'peers', 'activity', 'storage', 'settings'] as View[]).map((v, i) => `<button class="nav-item" data-view="${v}">${icon(['grid', 'devices', 'pulse', 'storage', 'settings'][i])}<span>${['Genel bakış', 'İstemciler', 'Etkinlik akışı', 'Depolama & izleme', 'Ayarlar'][i]}</span>${v === 'peers' ? '<span id="peer-nav-count" class="nav-count">0</span>' : ''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="quiet-card">${icon('leaf')}<strong>Az kaynak. Tam kontrol.</strong><p>İhtiyacınız kadar izleyin.<br>Yalnızca seçtiklerinizi saklayın.</p><button data-view="storage">Tercihleri yönet ${icon('arrow')}</button></div><div class="sidebar-status"><i class="live-dot"></i><span>Yerel konsol</span><span id="version"></span></div><button class="profile" id="profile-btn"><span class="avatar">Y</span><span><strong>Yönetici</strong><small id="profile-user">Yönetici hesabı</small></span>${icon('settings')}</button></div></aside><div class="main-wrap"><header class="topbar"><button class="icon-btn mobile-menu" id="mobile-menu" aria-label="Menüyü aç">${icon('menu')}</button><div class="breadcrumb"><span>Çalışma alanım</span>${icon('chevron')}<strong id="breadcrumb-current">Genel bakış</strong></div><div class="topbar-right"><span id="connection" class="connection"><i class="live-dot"></i>Canlı bağlantı</span><button class="icon-btn" id="activity-shortcut" aria-label="Etkinlik akışını aç">${icon('bell')}<span class="notification-dot"></span></button><span class="top-divider"></span><span class="top-avatar">Y</span></div></header><div id="demo-notice"></div><main id="main"></main><footer><span>WireGuard Simple <span class="footer-separator">/</span> Ağınız sizin kontrolünüzde.</span><span id="footer-mode"></span></footer></div></div>`;
  document.querySelectorAll<HTMLButtonElement>('[data-view]').forEach(button => button.addEventListener('click', () => navigate(button.dataset.view as View)));
  document.querySelector('.brand')?.addEventListener('click', event => { event.preventDefault(); navigate('overview'); });
  document.querySelector('#profile-btn')?.addEventListener('click', () => navigate('settings'));
  document.querySelector('#activity-shortcut')?.addEventListener('click', () => navigate('activity'));
  document.querySelector('#mobile-menu')?.addEventListener('click', () => { const opened = document.querySelector('.sidebar')?.classList.toggle('mobile-open'); document.querySelector('#mobile-menu')?.setAttribute('aria-expanded', String(opened)); });
}
function updateChrome(): void {
  if (!state || !document.querySelector('.shell')) return;
  const names: Record<View, string> = { overview: 'Genel bakış', peers: 'İstemciler', activity: 'Etkinlik akışı', storage: 'Depolama & izleme', settings: 'Ayarlar' };
  document.querySelectorAll<HTMLButtonElement>('.nav-item').forEach(button => { button.classList.toggle('active', button.dataset.view === view); if (button.dataset.view === view) button.setAttribute('aria-current', 'page'); else button.removeAttribute('aria-current'); });
  document.querySelector('#breadcrumb-current')!.textContent = names[view]; document.title = `${names[view]} · WireGuard Simple`;
  document.querySelector('#peer-nav-count')!.textContent = String(state.peers.length);
  document.querySelector('#version')!.textContent = `v${state.version.replace('-dev', '')}`;
  document.querySelector('#profile-user')!.textContent = session.user;
  document.querySelector('#connection')!.innerHTML = failures ? `${icon('info')}Yeniden bağlanıyor` : '<i class="live-dot"></i>Canlı bağlantı';
  document.querySelector('#connection')!.classList.toggle('offline', failures > 0);
  document.querySelector('#footer-mode')!.textContent = state.mode === 'demo' ? 'DEMO ÇALIŞMA ALANI · YALNIZCA ÖRNEK VERİLER' : 'YEREL YÖNETİM · LINUX';
  document.querySelector('#demo-notice')!.innerHTML = state.mode === 'demo' ? `<div class="demo-notice">${icon('shield')}<span><strong>Güvenli önizleme.</strong> İstemciler ve trafik örnektir; bu bilgisayarın VPN veya ağ ayarları değişmez.</span><span class="demo-pill">DEMO</span></div>` : '';
}
function pageHead(eyebrow: string, title: string, subtitle: string, buttons = ''): string { return `<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${subtitle}</p></div><div class="page-actions">${buttons}</div></div>`; }
function addButton(): string { return `<button class="btn primary" data-action="add">${icon('plus')}İstemci ekle</button>`; }
function empty(iconName: string, title: string, text: string, button = ''): string { return `<div class="empty">${icon(iconName)}<h3>${title}</h3><p>${text}</p>${button}</div>`; }

function renderMain(): void {
  if (!state) return;
  const main = document.querySelector<HTMLElement>('#main')!;
  if (view === 'overview') main.innerHTML = overview();
  else if (view === 'peers') main.innerHTML = peersPage();
  else if (view === 'activity') main.innerHTML = activityPage();
  else if (view === 'storage') main.innerHTML = storagePage();
  else main.innerHTML = settingsPage();
  bindMain();
}
function overview(): string {
  const active = state.peers.filter(p => p.status === 'active').length;
  const rx = state.peers.reduce((n, p) => n + p.rxRate, 0), tx = state.peers.reduce((n, p) => n + p.txRate, 0);
  const total = state.peers.reduce((n, p) => n + p.rxBytes + p.txBytes, 0);
  return `${pageHead('AĞ KONSOLU', 'Ağınız, bir bakışta.', 'Bağlantılarınız, trafik ve sunucu sağlığı. Hepsi tek yerde.', `<span class="date-chip">${icon('clock')}${new Date().toLocaleDateString('tr-TR', { day: 'numeric', month: 'long', year: 'numeric' })}</span>${addButton()}`)}
  ${state.warnings.length ? `<div class="warning-bar">${icon('info')}<div>${state.warnings.map(esc).join('<br>')}</div></div>` : ''}
  <div class="stat-grid"><article class="stat-card"><div class="stat-top"><span>Aktif istemci</span><span class="stat-icon">${icon('devices')}</span></div><div class="stat-value">${active}<span>/ ${state.peers.length}</span></div><div class="stat-foot"><span class="tiny-dot green-dot"></span>Son 3 dk içinde handshake</div><svg class="stat-decoration" viewBox="0 0 100 30"><path d="m0 26 12-5 13 3 10-10 11 3 10-7 13 2L83 4l17 4"/></svg></article>
  <article class="stat-card"><div class="stat-top"><span>Anlık trafik</span><span class="stat-icon">${icon('pulse')}</span></div><div class="stat-value compact">${rate(rx + tx).split(' ')[0]}<span>${rate(rx + tx).split(' ')[1]}</span></div><div class="stat-foot"><span class="rx-text">↓ ${rate(rx)}</span><span class="tx-text">↑ ${rate(tx)}</span></div><div class="mini-bars" aria-hidden="true">${[4, 2, 5, 3, 6, 4, 7, 5, 8, 6, 9, 7].map(n => `<i class="bar-${n}"></i>`).join('')}</div></article>
  <article class="stat-card"><div class="stat-top"><span>Aktarılan veri</span><span class="stat-icon">${icon('down')}</span></div><div class="stat-value compact">${bytes(total).split(' ')[0]}<span>${bytes(total).split(' ')[1]}</span></div><div class="stat-foot">Mevcut WireGuard sayaçları</div><span class="stat-note">RX + TX</span></article>
  <article class="stat-card"><div class="stat-top"><span>Uygulama belleği</span><span class="stat-icon">${icon('leaf')}</span></div><div class="stat-value compact">${bytes(state.resources.appMemory).split(' ')[0]}<span>${bytes(state.resources.appMemory).split(' ')[1]}</span></div><div class="stat-foot"><span class="tiny-dot green-dot"></span>${state.settings.historyEnabled ? 'Geçmiş kaydı açık' : 'Kalıcı trafik kaydı kapalı'}</div><span class="soft-tag">HAFİF ÇEKİRDEK</span></article></div>
  <div class="dashboard-columns"><div class="dashboard-primary"><section class="panel traffic-panel"><div class="panel-head"><div><h2>Canlı trafik <span class="badge subtle">${icon('pulse')}CANLI</span></h2><p>Tüm istemcilerin toplam veri akışı</p></div><div class="segmented" aria-label="Grafik kaynağı"><button class="${chartMode === 'live' ? 'selected' : ''}" data-chart="live">Canlı</button><button class="${chartMode === 'history' ? 'selected' : ''}" data-chart="history">Geçmiş ${!state.settings.historyEnabled ? icon('lock') : ''}</button></div></div>${chartMode === 'history' && !state.settings.historyEnabled ? `<div class="chart-locked">${icon('storage')}<h3>Geçmiş, sizin tercihiniz.</h3><p>Canlı izleme diske yazmaz. Geçmişi açtığınızda süre ve alan sınırını siz belirlersiniz.</p><button class="btn secondary" data-go="storage">İzleme tercihleri ${icon('arrow')}</button></div>` : graph(chartMode === 'history' ? history : state.points)}<div class="chart-footer"><span><i class="legend rx"></i>Alınan (RX)</span><span><i class="legend tx"></i>Gönderilen (TX)</span><span class="chart-footnote">${chartMode === 'history' ? 'Sınırlı kalıcı geçmiş' : `${state.points.length} örnek · RAM tamponu`}</span></div></section>
  <section class="panel clients-panel"><div class="panel-head"><div><h2>İstemciler <span class="count-chip">${state.peers.length}</span></h2><p>Ağınızdaki cihazlar ve son durumları</p></div><button class="text-btn" data-go="peers">Tümünü gör ${icon('arrow')}</button></div>${peerTable(state.peers.slice(0, 5), true)}<div class="table-note">${icon('info')}Aktiflik, son handshake zamanına göre tahmindir.</div></section></div>
  <aside class="dashboard-secondary"><section class="panel health-panel"><div class="panel-head"><h2>Sunucu sağlığı</h2><span class="badge ${state.interfaceUp ? 'green' : 'amber'}"><i></i>${state.interfaceUp ? 'Çalışıyor' : 'Kontrol gerekli'}</span></div><div class="server-identity"><span class="server-icon">${icon('server')}</span><div><strong>${esc(state.server.name)}</strong><span>${esc(state.server.interface)} <b>·</b> ${esc(state.server.address)}</span></div></div><div class="resource"><div><span>İşlemci</span><strong>${state.mode === 'demo' ? '—' : `${state.resources.hostCPU.toFixed(1)}%`}</strong></div><progress max="100" value="${state.mode === 'demo' ? 0 : state.resources.hostCPU}"></progress><small>${state.mode === 'demo' ? 'Gerçek Linux sunucusunda ölçülür' : 'Sunucu genelindeki kullanım'}</small></div><div class="resource"><div><span>Sistem belleği</span><strong>${state.resources.hostMemoryTotal ? `${Math.round(state.resources.hostMemoryUsed / state.resources.hostMemoryTotal * 100)}%` : '—'}</strong></div><progress max="${state.resources.hostMemoryTotal || 1}" value="${state.resources.hostMemoryUsed}"></progress><small>${state.resources.hostMemoryTotal ? `${bytes(state.resources.hostMemoryUsed)} / ${bytes(state.resources.hostMemoryTotal)}` : 'Gerçek Linux sunucusunda ölçülür'}</small></div><div class="health-meta"><div><span>Uygulama verisi</span><strong>${bytes(state.resources.controlBytes + state.resources.telemetryBytes)}</strong></div><div><span>Arayüz</span><strong class="mono">${esc(state.server.interface)} : ${state.server.port}</strong></div></div><button class="btn secondary full" data-go="settings">Sunucu ayarları ${icon('arrow')}</button></section>
  <section class="lightweight-card"><span class="leaf-circle">${icon('leaf')}</span><div class="eyebrow">KONTROL SİZDE</div><h2>Gerektiği kadar izleme.<br>Fazlası değil.</h2><p>${state.settings.historyEnabled ? 'Geçmiş kayıtları seçtiğiniz disk bütçesi içinde tutuluyor.' : 'Canlı veriler bellekte. Trafik geçmişi siz açana kadar diske yazılmaz.'}</p><div class="lightweight-meta"><span><i class="tiny-dot green-dot"></i>${state.settings.historyEnabled ? `${state.settings.retentionDays} gün saklama` : 'Geçmiş kapalı'}</span><span>${bytes(state.resources.telemetryBytes)} kayıt</span></div><button class="text-btn" data-go="storage">Depolama & izleme ${icon('arrow')}</button></section>
  <section class="panel recent-panel"><div class="panel-head"><h2>Son etkinlikler</h2><button class="icon-btn" data-go="activity" aria-label="Bütün etkinlikler">${icon('arrow')}</button></div>${eventList(state.events.slice(-3).reverse(), true)}</section></aside></div>`;
}

function graph(points: Point[]): string {
  if (points.length < 2) return `<div class="chart-wait">${icon('pulse')}<strong>${chartMode === 'history' ? 'Henüz geçmiş örneği yok' : 'İlk ölçümler toplanıyor'}</strong><span>${chartMode === 'history' ? 'Seçtiğiniz örnekleme aralığında kayıtlar burada görünecek.' : 'Canlı trafik grafiği birkaç saniye içinde görünecek.'}</span></div>`;
  const w = 760, h = 210, left = 0, max = Math.max(10000, ...points.flatMap(p => [p.rx, p.tx])) * 1.25;
  const make = (key: 'rx' | 'tx'): string => points.map((p, i) => `${i === 0 ? 'M' : 'L'}${(left + i / (points.length - 1) * w).toFixed(1)},${(h - p[key] / max * (h - 8)).toFixed(1)}`).join(' ');
  const rx = make('rx'), tx = make('tx');
  const labels = [0, 1, 2, 3, 4].map(i => points[Math.round((points.length - 1) * i / 4)]);
  return `<div class="chart"><div class="chart-y">${[1, .75, .5, .25, 0].map(n => `<span>${rate(max * n)}</span>`).join('')}</div><div class="chart-drawing"><svg viewBox="0 0 ${w} ${h}" preserveAspectRatio="none" role="img" aria-label="Alınan ve gönderilen trafik grafiği"><defs><linearGradient id="rx-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#4e8b66" stop-opacity=".2"/><stop offset="100%" stop-color="#4e8b66" stop-opacity=".01"/></linearGradient></defs>${[0, .25, .5, .75, 1].map(n => `<line x1="0" y1="${n * h}" x2="${w}" y2="${n * h}" stroke="#e9ede8" stroke-dasharray="4 5"/>`).join('')}<path d="${rx} L${w},${h} L0,${h} Z" fill="url(#rx-fill)"/><path d="${tx} L${w},${h} L0,${h} Z" fill="#8b9dab" fill-opacity=".04"/><path d="${rx}" fill="none" stroke="#4c8866" stroke-width="2.5" vector-effect="non-scaling-stroke" stroke-linejoin="round"/><path d="${tx}" fill="none" stroke="#94a4b4" stroke-width="2" vector-effect="non-scaling-stroke" stroke-linejoin="round"/></svg><div class="chart-x">${labels.map(p => `<span>${time(p.time)}</span>`).join('')}</div></div></div>`;
}
function peerTable(peers: Peer[], compact = false): string {
  if (!peers.length) return empty('devices', query ? 'Eşleşen istemci yok' : 'İlk bağlantınızı oluşturun', query ? 'Farklı bir isim veya IP adresi arayın.' : 'Bir istemci ekleyin, yapılandırmayı indirin ve bağlanın.', !query ? addButton() : '');
  return `<div class="table-scroll"><table class="peer-table"><thead><tr><th>İSTEMCİ</th><th>DURUM</th><th>AKTARIM</th><th>SON HANDSHAKE</th><th class="align-right">İŞLEMLER</th></tr></thead><tbody>${peers.map((p, i) => `<tr><td><div class="peer-name"><span class="device-avatar color-${i % 4}">${icon(/phone|pixel|iphone/i.test(p.name) ? 'devices' : /sunucu|server/i.test(p.name) ? 'server' : 'devices')}</span><div><strong>${esc(p.name)}</strong><span class="mono">${esc(p.address)}</span></div></div></td><td>${status(p)}</td><td><div class="transfer"><span>↓ ${bytes(p.rxBytes)}</span><small>↑ ${bytes(p.txBytes)}</small></div></td><td><span class="handshake">${ago(p.lastHandshake)}</span>${!compact && p.expiresAt ? `<small class="expires">Bitiş: ${date(p.expiresAt)}</small>` : ''}</td><td><div class="row-actions"><button class="icon-btn" data-qr="${esc(p.id)}" aria-label="${esc(p.name)} QR kodu" title="QR kodu" ${!p.hasConfig ? 'disabled' : ''}>${icon('qr')}</button><button class="icon-btn" data-download="${esc(p.id)}" aria-label="${esc(p.name)} yapılandırmasını indir" title="Yapılandırmayı indir" ${!p.hasConfig ? 'disabled' : ''}>${icon('down')}</button><button class="icon-btn" data-detail="${esc(p.id)}" aria-label="${esc(p.name)} ayrıntıları" title="İstemci ayrıntıları">${icon('dots')}</button></div></td></tr>`).join('')}</tbody></table></div>`;
}
function peersPage(): string {
  const peers = state.peers.filter(p => (peerFilter === 'all' || p.status === peerFilter) && `${p.name} ${p.address} ${p.endpoint}`.toLocaleLowerCase('tr').includes(query.toLocaleLowerCase('tr')));
  return `${pageHead('BAĞLANTILAR', 'İstemciler', 'Cihazlarınızı ekleyin, erişimlerini yönetin ve bağlantı durumlarını izleyin.', `<button class="btn secondary" data-action="import">${icon('upload')}İçe aktar</button>${addButton()}`)}<div class="peer-summary"><span><i class="tiny-dot green-dot"></i><strong>${state.peers.filter(p => p.status === 'active').length}</strong> aktif</span><span><i class="tiny-dot amber-dot"></i><strong>${state.peers.filter(p => p.status === 'idle').length}</strong> beklemede</span><span><i class="tiny-dot gray-dot"></i><strong>${state.peers.filter(p => !p.enabled).length}</strong> devre dışı</span></div><section class="panel"><div class="table-toolbar"><div class="filter-tabs">${[['all', 'Tümü'], ['active', 'Aktif'], ['idle', 'Beklemede'], ['disabled', 'Devre dışı']].map(([key, label]) => `<button class="${peerFilter === key ? 'selected' : ''}" data-filter="${key}">${label}${key === 'all' ? `<span>${state.peers.length}</span>` : ''}</button>`).join('')}</div><label class="search-box">${icon('search')}<input id="peer-search" placeholder="İsim veya IP adresi ara…" value="${esc(query)}" aria-label="İstemci ara"/><kbd>/</kbd></label></div><div id="peer-table-wrap">${peerTable(peers)}</div><div class="table-note">${icon('info')}Handshake tabanlı aktiflik bir tahmindir. Trafik sayaçları arayüz yeniden oluşturulunca sıfırlanabilir.</div></section>`;
}
function eventList(events: Event[], compact = false): string {
  if (!events.length) return empty('pulse', 'Henüz etkinlik yok', 'Yönetim işlemleri burada görünecek.');
  return `<div class="event-list ${compact ? 'compact' : ''}">${events.map(e => `<div class="event-row"><span class="event-symbol ${e.level}">${icon(e.level === 'warning' || e.level === 'error' ? 'info' : e.action.startsWith('peer') ? 'devices' : 'check')}</span><div><strong>${esc(e.detail)}</strong><span>${compact ? ago(e.time) : `${date(e.time)} · ${time(e.time)} · ${esc(e.action)}`}</span></div>${!compact ? `<span class="badge ${e.level === 'warning' ? 'amber' : e.level === 'error' ? 'red' : 'muted'}">${e.level === 'warning' ? 'Uyarı' : e.level === 'error' ? 'Hata' : 'Bilgi'}</span>` : ''}</div>`).join('')}</div>`;
}
function activityPage(): string { return `${pageHead('GÖZLEMLENEBİLİRLİK', 'Etkinlik akışı', 'İstemci işlemleri, yönetici girişleri ve sistem olayları.', `<button class="btn secondary" data-action="export-events">${icon('down')}Akışı dışa aktar</button>`)}<div class="info-strip">${icon(state.settings.auditEnabled ? 'storage' : 'leaf')}<div><strong>${state.settings.auditEnabled ? 'Kalıcı yönetim geçmişi açık' : 'Yalnızca bu çalışma oturumundaki son 200 olay'}</strong><span>${state.settings.auditEnabled ? 'Yeni olaylar süre ve disk bütçenizle sınırlı olarak saklanır.' : 'Uygulama yeniden başladığında bu akış temizlenir. Kalıcı kaydı tercihlerden açabilirsiniz.'}</span></div><button class="text-btn" data-go="storage">Tercihler ${icon('arrow')}</button></div><section class="panel"><div class="panel-head"><h2>Yönetim olayları <span class="count-chip">${state.events.length}</span></h2><span class="badge subtle"><i class="live-dot"></i>CANLI AKIŞ</span></div>${eventList([...state.events].reverse())}</section>`; }
function toggle(name: string, checked: boolean, label: string, text: string, tag = ''): string { return `<label class="toggle-row"><div class="toggle-description"><strong>${label}${tag ? `<span class="mini-label">${tag}</span>` : ''}</strong><p>${text}</p></div><span class="switch"><input type="checkbox" name="${name}" ${checked ? 'checked' : ''}/><span class="switch-track"></span></span></label>`; }
function storagePage(): string {
  const cfg = state.settings, r = state.resources;
  return `${pageHead('KAYNAK YÖNETİMİ', 'Depolama & izleme', 'Daha fazla görünürlük, yalnızca ihtiyacınız olduğunda. Sınırları siz belirleyin.')}<div class="settings-layout"><form id="storage-form" class="settings-primary"><section class="panel"><div class="panel-head"><div><h2>İzleme tercihleri</h2><p>Ağ trafiği ve olaylar için neyin saklanacağını seçin.</p></div><span class="badge green">${icon('leaf')}HAFİF VARSAYILANLAR</span></div><div class="toggle-rows"><div class="always-on"><div><strong>Canlı izleme</strong><p>Son ölçümler RAM'de tutulur. Kalıcı trafik verisi yazılmaz.</p></div><span class="badge green"><i></i>Her zaman açık</span></div>${toggle('historyEnabled', cfg.historyEnabled, 'Trafik geçmişi', 'Toplam trafik ve istemci sayaçlarını belirli aralıklarla kaydet.', 'İSTEĞE BAĞLI')}${toggle('auditEnabled', cfg.auditEnabled, 'Yönetim işlem geçmişi', 'İstemci işlemlerini, giriş denemelerini ve ayar değişikliklerini diskte sakla.')}${toggle('metricsEnabled', cfg.metricsEnabled, 'Prometheus metrikleri', 'Erişim anahtarıyla korunan /metrics uç noktasını aç. Ayrı bir izleme servisi kurulmaz.')}</div></section><section class="panel"><div class="panel-head"><div><h2>Saklama sınırları</h2><p>Kalıcı kayıtlar açıldığında bu bütçe uygulanır.</p></div>${icon('storage')}</div><div class="form-grid storage-fields"><label>Saklama süresi<div class="input-unit"><input name="retentionDays" type="number" min="1" max="30" required value="${cfg.retentionDays}"/><span>gün</span></div><small>1–30 gün; eski kayıtlar temizlenir.</small></label><label>Toplam geçmiş bütçesi<div class="input-unit"><input name="budgetMB" type="number" min="16" max="512" required value="${cfg.budgetMB}"/><span>MB</span></div><small>Geçmiş veritabanı ve işlem günlüğü dahil.</small></label><label>Örnekleme aralığı<select name="sampleSeconds">${[30, 60, 120, 300, 600, 3600].map(n => `<option value="${n}" ${cfg.sampleSeconds === n ? 'selected' : ''}>${n < 60 ? `${n} saniye` : `${n / 60} dakika`}</option>`).join('')}</select><small>Daha seyrek örnekleme, daha az disk yazımı.</small></label></div><div class="policy-note">${icon('shield')}Boş alan 64 MB altına düştüğünde geçmiş kaydı duraklatılır. Mevcut VPN bağlantıları devam eder.</div></section><div class="form-actions"><span>Değişiklikler kaydettiğinizde uygulanır.</span><button class="btn primary" type="submit">${icon('check')}Tercihleri kaydet</button></div></form><aside class="settings-secondary"><section class="budget-card"><span class="eyebrow">DEPOLAMA ÖZETİ</span><h2>${bytes(r.telemetryBytes)}<span>/ ${cfg.budgetMB} MB</span></h2><progress value="${r.telemetryBytes}" max="${cfg.budgetMB * 1024 ** 2}"></progress><div class="budget-status"><i class="tiny-dot ${state.historyPaused ? 'amber-dot' : 'green-dot'}"></i>${state.historyPaused ? 'Kayıt duraklatıldı' : cfg.historyEnabled || cfg.auditEnabled ? 'Seçili kayıtlar etkin' : 'Kalıcı kayıt kapalı'}</div><dl><div><dt>Yapılandırma verisi</dt><dd>${bytes(r.controlBytes)}</dd></div><div><dt>Geçmiş + günlük dosyaları</dt><dd>${bytes(r.telemetryBytes)}</dd></div><div><dt>Diskte boş alan</dt><dd>${bytes(r.diskFree)}</dd></div></dl><p>Yapılandırma, geçmişten ayrı tutulur. Kayıt kapatıldığında mevcut geçmiş, süresi dolana veya siz temizleyene kadar saklanır.</p></section><section class="panel cleanup-card"><h3>Geçmişi temizle</h3><p>Trafik ve kalıcı olay kayıtlarını kaldırır. İstemciler ve sunucu ayarları korunur.</p><button class="btn danger-outline full" type="button" data-action="clear-history">${icon('trash')}Kalıcı geçmişi temizle</button></section></aside></div>`;
}
function field(label: string, name: string, value: string | number, help = '', extra = ''): string { return `<label>${label}<input name="${name}" value="${esc(value)}" ${extra}/>${help ? `<small>${help}</small>` : ''}</label>`; }
function settingsPage(): string {
  const s = state.server;
  return `${pageHead('YAPILANDIRMA', 'Sunucu ayarları', 'Bağlantı bilgilerinizi ve yönetici erişiminizi yönetin.')}<div class="settings-layout"><div class="settings-primary"><form id="server-form" class="panel"><div class="panel-head"><div><h2>WireGuard sunucusu</h2><p>Yapılandırma değişiklikleri seçili arayüze uygulanır.</p></div><span class="badge muted mono">${esc(s.interface)}</span></div><div class="form-grid">${field('Sunucu adı', 'name', s.name, '', 'required maxlength="64"')}${field('Endpoint', 'endpoint', s.endpoint, 'İstemcilerin bağlanacağı genel IP veya alan adı.', 'placeholder="vpn.example.com"')}${field('VPN adresi', 'address', s.address, 'Örnek: 10.64.0.1/24', 'required')}${field('UDP portu', 'port', s.port, '', 'type="number" min="1" max="65535" required')}${field('DNS sunucuları', 'dns', s.dns, 'Virgülle ayrılmış IP adresleri.', 'required')}${field('İstemci Allowed IPs', 'allowedIPs', s.allowedIPs, 'Örnek: 0.0.0.0/0 veya özel alt ağlar.', 'required')}${field('MTU', 'mtu', s.mtu, 'Çalışan arayüzde adres/MTU değişikliği bakım gerektirir.', 'type="number" min="1280" max="1500" required')}</div><div class="panel-form-footer"><button class="btn primary" type="submit">${icon('check')}Sunucu ayarlarını uygula</button></div></form><section class="panel import-card"><span class="server-icon">${icon('upload')}</span><div><h3>Mevcut WireGuard yapılandırmanız mı var?</h3><p>Sunucu .conf dosyasından arayüz ve istemcileri içe aktarın. Çalıştırılabilir hook'lar kabul edilmez.</p></div><button class="btn secondary" data-action="import">İçe aktar</button></section><form id="password-form" class="panel"><div class="panel-head"><div><h2>Yönetici parolası</h2><p>${state.mode === 'demo' ? 'Gerçek Linux kurulumunda etkinleşir.' : 'Parola değiştiğinde bütün yönetici oturumları kapatılır.'}</p></div>${icon('lock')}</div><div class="form-grid"><label>Mevcut parola<input name="current" type="password" autocomplete="current-password" required ${state.mode === 'demo' ? 'disabled' : ''}/></label><label>Yeni parola<input name="password" type="password" autocomplete="new-password" minlength="12" maxlength="256" required ${state.mode === 'demo' ? 'disabled' : ''}/><small>En az 12 karakter.</small></label></div><div class="panel-form-footer"><button class="btn secondary" ${state.mode === 'demo' ? 'disabled' : ''}>Parolayı değiştir</button></div></form></div><aside class="settings-secondary"><section class="panel server-info-card"><span class="server-icon">${icon('shield')}</span><h3>Bağımsız bir yönetim katmanı</h3><p>WireGuard trafiğini Linux çekirdeği işler. Panel kapansa da mevcut VPN bağlantıları çalışır.</p><dl><div><dt>Arayüz</dt><dd class="mono">${esc(s.interface)}</dd></div><div><dt>Durum</dt><dd>${state.interfaceUp ? 'Çalışıyor' : 'Hazır değil'}</dd></div><div><dt>Sürüm</dt><dd>${esc(state.version)}</dd></div><div><dt>Çalışma süresi</dt><dd>${ago(state.startedAt).replace(' önce', '')}</dd></div></dl><label class="key-label">SUNUCU AÇIK ANAHTARI</label><code>${esc(s.publicKey)}</code><button class="text-btn" data-action="copy-key">${icon('copy')}Açık anahtarı kopyala</button></section>${state.mode !== 'demo' ? `<button class="btn secondary full" data-action="logout">${icon('logout')}Oturumu kapat</button>` : ''}</aside></div>`;
}

function bindMain(): void {
  document.querySelectorAll<HTMLProgressElement>('.resource progress').forEach(progress => progress.setAttribute('aria-label', progress.closest('.resource')?.querySelector('div span')?.textContent ?? 'Sunucu kaynağı'));
  document.querySelector('.budget-card progress')?.setAttribute('aria-label','Geçmiş depolama bütçesi kullanımı');
  if (view === 'storage' && state.settings.metricsEnabled) {
    document.querySelector('#storage-form > .panel')?.insertAdjacentHTML('afterend', `<section class="panel"><div class="panel-head"><div><h2>Metrik erişimi</h2><p>Prometheus için salt okunur ve bağımsız bir erişim anahtarı oluşturun.</p></div>${icon('pulse')}</div><div class="metrics-info"><code>/metrics</code><p>Bearer anahtarını izleme sisteminize ekleyin. Anahtar yalnızca metrikleri okuyabilir.</p><button class="btn secondary" type="button" id="create-metrics-token">Erişim anahtarı oluştur / yenile</button></div></section>`);
    document.querySelector('#create-metrics-token')?.addEventListener('click', () => action(async () => {
      const result = await api<{ token: string }>('/api/metrics-token', 'POST');
      openDialog('Metrik erişim anahtarı', `<p class="modal-subtitle">Bu anahtar yalnızca şimdi görüntülenir. Yeni anahtar oluşturmak önceki anahtarı geçersiz kılar.</p><code class="public-key">${esc(result.token)}</code><div class="modal-note metrics-note">${icon('lock')}Yalnızca metrik okuma yetkisi verir. Yönetim işlemi yapamaz.</div><div class="modal-actions"><button class="btn primary" id="copy-metrics-token">${icon('copy')}Anahtarı kopyala</button></div>`);
      modal.querySelector('#copy-metrics-token')!.addEventListener('click', () => action(async () => { await navigator.clipboard.writeText(result.token); toast('Metrik anahtarı kopyalandı'); }));
    }));
  }
  document.querySelectorAll<HTMLButtonElement>('[data-action="add"]').forEach(el => el.addEventListener('click', createDialog));
  document.querySelectorAll<HTMLButtonElement>('[data-go]').forEach(el => el.addEventListener('click', () => navigate(el.dataset.go as View)));
  document.querySelectorAll<HTMLButtonElement>('[data-chart]').forEach(el => el.addEventListener('click', () => action(async () => { chartMode = el.dataset.chart!; if (chartMode === 'history' && state.settings.historyEnabled) history = await api<Point[]>('/api/history'); renderMain(); })));
  document.querySelectorAll<HTMLButtonElement>('[data-qr]').forEach(el => el.addEventListener('click', () => action(() => qrDialog(el.dataset.qr!))));
  document.querySelectorAll<HTMLButtonElement>('[data-download]').forEach(el => el.addEventListener('click', () => action(() => downloadConfig(el.dataset.download!))));
  document.querySelectorAll<HTMLButtonElement>('[data-detail]').forEach(el => el.addEventListener('click', () => detailDialog(el.dataset.detail!)));
  document.querySelectorAll<HTMLButtonElement>('[data-filter]').forEach(el => el.addEventListener('click', () => { peerFilter = el.dataset.filter!; renderMain(); }));
  document.querySelector<HTMLInputElement>('#peer-search')?.addEventListener('input', event => {
    query = (event.target as HTMLInputElement).value;
    const peers = state.peers.filter(p => (peerFilter === 'all' || p.status === peerFilter) && `${p.name} ${p.address} ${p.endpoint}`.toLocaleLowerCase('tr').includes(query.toLocaleLowerCase('tr')));
    document.querySelector('#peer-table-wrap')!.innerHTML = peerTable(peers);
    document.querySelectorAll<HTMLButtonElement>('#peer-table-wrap [data-qr]').forEach(el => el.addEventListener('click', () => action(() => qrDialog(el.dataset.qr!))));
    document.querySelectorAll<HTMLButtonElement>('#peer-table-wrap [data-download]').forEach(el => el.addEventListener('click', () => action(() => downloadConfig(el.dataset.download!))));
    document.querySelectorAll<HTMLButtonElement>('#peer-table-wrap [data-detail]').forEach(el => el.addEventListener('click', () => detailDialog(el.dataset.detail!)));
    document.querySelectorAll<HTMLButtonElement>('#peer-table-wrap [data-action="add"]').forEach(el => el.addEventListener('click', createDialog));
  });
  document.querySelectorAll<HTMLButtonElement>('[data-action="import"]').forEach(el => el.addEventListener('click', importDialog));
  document.querySelector('[data-action="clear-history"]')?.addEventListener('click', () => confirmDialog('Kalıcı geçmiş temizlensin mi?', 'Trafik ve kalıcı yönetim kayıtları silinecek. İstemcileriniz ve ayarlarınız korunacak.', 'Geçmişi temizle', async () => { await api('/api/history', 'DELETE'); closeDialog(); await refresh(true); navigate('storage'); toast('Kalıcı geçmiş temizlendi'); }));
  document.querySelector('[data-action="export-events"]')?.addEventListener('click', () => { download(new Blob([JSON.stringify(state.events, null, 2)], { type: 'application/json' }), `wgs-etkinlik-${new Date().toISOString().slice(0, 10)}.json`); toast('Görünen etkinlikler dışa aktarıldı'); });
  document.querySelector('[data-action="copy-key"]')?.addEventListener('click', () => action(async () => { await navigator.clipboard.writeText(state.server.publicKey); toast('Açık anahtar kopyalandı'); }));
  document.querySelector('[data-action="logout"]')?.addEventListener('click', () => action(async () => { await api('/api/logout', 'POST'); clearInterval(poll); session.authenticated = false; renderAuth(); }));
  document.querySelector<HTMLFormElement>('#storage-form')?.addEventListener('submit', event => { event.preventDefault(); const form = event.currentTarget as HTMLFormElement; void submitForm(form, async () => { const f = new FormData(form); await api('/api/settings', 'PUT', { historyEnabled: f.has('historyEnabled'), auditEnabled: f.has('auditEnabled'), metricsEnabled: f.has('metricsEnabled'), retentionDays: Number(f.get('retentionDays')), budgetMB: Number(f.get('budgetMB')), sampleSeconds: Number(f.get('sampleSeconds')) }); await refresh(true); renderMain(); toast('İzleme tercihleri kaydedildi'); }); });
  document.querySelector<HTMLFormElement>('#server-form')?.addEventListener('submit', event => { event.preventDefault(); const form = event.currentTarget as HTMLFormElement; void submitForm(form, async () => { const f = new FormData(form); await api('/api/server', 'PUT', { ...state.server, name: String(f.get('name')), endpoint: String(f.get('endpoint')).trim(), address: String(f.get('address')).trim(), port: Number(f.get('port')), dns: String(f.get('dns')), allowedIPs: String(f.get('allowedIPs')), mtu: Number(f.get('mtu')) }); await refresh(true); toast(state.mode === 'demo' ? 'Demo sunucu ayarları güncellendi' : 'Sunucu ayarları uygulandı'); }); });
  document.querySelector<HTMLFormElement>('#password-form')?.addEventListener('submit', event => { event.preventDefault(); const form = event.currentTarget as HTMLFormElement; void submitForm(form, async () => { const f = new FormData(form); await api('/api/password', 'POST', { current: f.get('current'), password: f.get('password') }); clearInterval(poll); session.authenticated = false; renderAuth(); toast('Parola değiştirildi. Yeniden giriş yapın.'); }); });
}
async function submitForm(form: HTMLFormElement, fn: () => Promise<void>): Promise<void> { const button = form.querySelector<HTMLButtonElement>('button[type="submit"]') ?? form.querySelector<HTMLButtonElement>('button:last-child'); if (button) button.disabled = true; await action(fn); if (button) button.disabled = false; }
function openDialog(title: string, content: string, cls = ''): void {
  if (modal.open) modal.close(); modal.className = cls; modal.innerHTML = `<div class="modal-head"><div><div class="eyebrow">WIREGUARD SIMPLE</div><h2 id="modal-title">${title}</h2></div><button class="icon-btn" id="close-modal" aria-label="Pencereyi kapat">${icon('close')}</button></div>${content}`;
  modal.querySelector('#close-modal')!.addEventListener('click', closeDialog); modal.showModal();
}
function closeDialog(): void { modal.close(); if (qrBlob) { URL.revokeObjectURL(qrBlob); qrBlob = ''; } modal.innerHTML = ''; }
modal.addEventListener('cancel', event => { event.preventDefault(); closeDialog(); });
modal.addEventListener('click', event => { if (event.target === modal) { const box = modal.getBoundingClientRect(); if (event.clientX < box.left || event.clientX > box.right || event.clientY < box.top || event.clientY > box.bottom) closeDialog(); } });
function createDialog(): void {
  openDialog('Yeni istemci', `<p class="modal-subtitle">Cihazınıza bir isim verin. Anahtarları ve boş bir IP adresini sizin için hazırlayalım.</p><form id="create-form"><div class="form-grid single"><label>İstemci adı<input name="name" placeholder="Örn. İş MacBook'um" required maxlength="64" autocomplete="off" autofocus/></label><label>Erişim bitiş tarihi <span class="optional">İsteğe bağlı</span><input name="expires" type="datetime-local" min="${new Date(Date.now() + 60000).toLocaleString('sv-SE').slice(0, 16).replace(' ', 'T')}"/><small>Boş bırakırsanız süre sınırı uygulanmaz.</small></label></div><div class="modal-note">${icon('shield')}Her istemci için bağımsız bir anahtar çifti oluşturulur.</div><div class="modal-actions"><button class="btn secondary" type="button" id="cancel-create">Vazgeç</button><button class="btn primary" type="submit">${icon('plus')}İstemciyi oluştur</button></div></form>`);
  modal.querySelector('#cancel-create')!.addEventListener('click', closeDialog);
  modal.querySelector<HTMLFormElement>('#create-form')!.addEventListener('submit', event => { event.preventDefault(); const form = event.currentTarget as HTMLFormElement; void submitForm(form, async () => { const f = new FormData(form); const expires = String(f.get('expires')); const peer = await api<Peer>('/api/peers', 'POST', { name: f.get('name'), expiresAt: expires ? new Date(expires).toISOString() : null }); closeDialog(); await refresh(true); toast('İstemci oluşturuldu'); detailDialog(peer.id); }); });
}
function detailDialog(id: string): void {
  const p = state.peers.find(p => p.id === id); if (!p) return;
  openDialog(esc(p.name), `<div class="detail-status">${status(p)}<span class="mono">${esc(p.address)}</span></div><dl class="peer-details"><div><dt>Son handshake</dt><dd>${ago(p.lastHandshake)}</dd></div><div><dt>Alınan / gönderilen</dt><dd>${bytes(p.rxBytes)} / ${bytes(p.txBytes)}</dd></div><div><dt>Endpoint</dt><dd class="mono">${esc(p.endpoint || 'Henüz bilinmiyor')}</dd></div><div><dt>Erişim bitişi</dt><dd>${p.expiresAt ? new Date(p.expiresAt).toLocaleString('tr-TR') : 'Süresiz'}</dd></div></dl><label class="key-label">İSTEMCİ AÇIK ANAHTARI</label><code class="public-key">${esc(p.publicKey)}</code>${!p.hasConfig ? '<p class="modal-subtitle">Bu istemci sunucu yapılandırmasından içe aktarıldı. Özel anahtarı bulunmadığından QR ve yapılandırma üretilemez.</p>' : ''}<div class="detail-downloads"><button class="btn secondary" id="detail-qr" ${!p.hasConfig ? 'disabled' : ''}>${icon('qr')}QR kodu</button><button class="btn primary" id="detail-download" ${!p.hasConfig ? 'disabled' : ''}>${icon('down')}Yapılandırma</button></div><div class="detail-danger"><button class="text-btn" id="toggle-peer">${icon(p.enabled ? 'pause' : 'play')}${p.enabled ? 'Erişimi duraklat' : 'Erişimi etkinleştir'}</button><button class="text-btn red-text" id="delete-peer">${icon('trash')}İstemciyi sil</button></div>`);
  modal.querySelector('#detail-qr')!.addEventListener('click', () => action(() => qrDialog(id)));
  modal.querySelector('#detail-download')!.addEventListener('click', () => action(() => downloadConfig(id)));
  modal.querySelector('#toggle-peer')!.addEventListener('click', () => action(async () => { await api(`/api/peers/${id}`, 'PATCH', { enabled: !p.enabled }); closeDialog(); await refresh(true); toast(p.enabled ? 'İstemci erişimi duraklatıldı' : 'İstemci etkinleştirildi'); }));
  modal.querySelector('#delete-peer')!.addEventListener('click', () => confirmDialog('İstemci silinsin mi?', `${esc(p.name)} için VPN erişimi ve bu sunucudaki anahtar kaydı kaldırılacak.`, 'İstemciyi sil', async () => { await api(`/api/peers/${id}`, 'DELETE'); closeDialog(); await refresh(true); toast('İstemci silindi'); }));
}
async function qrDialog(id: string): Promise<void> {
  const p = state.peers.find(p => p.id === id); if (!p) return;
  const response = await fetch(`/api/peers/${id}/qr`, { credentials: 'same-origin' }); if (!response.ok) { const error = await response.json(); throw new Error(error.error); }
  if (qrBlob) URL.revokeObjectURL(qrBlob); qrBlob = URL.createObjectURL(await response.blob());
  openDialog('Cihazınızı bağlayın', `<p class="modal-subtitle">${esc(p.name)} için WireGuard uygulamasını açın ve QR kodunu tarayın.</p><div class="qr-container"><img src="${qrBlob}" alt="${esc(p.name)} WireGuard yapılandırma QR kodu" width="280" height="280"/></div><p class="qr-warning">${icon('lock')}Bu QR kodu cihazın erişim anahtarını içerir. Paylaşmayın.</p><div class="modal-actions"><button class="btn secondary" id="qr-download">${icon('down')}Dosya olarak indir</button><button class="btn primary" id="qr-done">Tamam</button></div>`, 'qr-modal');
  modal.querySelector('#qr-done')!.addEventListener('click', closeDialog); modal.querySelector('#qr-download')!.addEventListener('click', () => action(() => downloadConfig(id)));
}
function download(blob: Blob, filename: string): void { const url = URL.createObjectURL(blob); const a = document.createElement('a'); a.href = url; a.download = filename; a.click(); setTimeout(() => URL.revokeObjectURL(url), 1000); }
async function downloadConfig(id: string): Promise<void> { const response = await fetch(`/api/peers/${id}/config`, { credentials: 'same-origin' }); if (!response.ok) { const error = await response.json(); throw new Error(error.error); } download(await response.blob(), `wireguard-${id}.conf`); toast('Yapılandırma indirildi'); }
function confirmDialog(title: string, text: string, label: string, fn: () => Promise<void>): void { openDialog(title, `<p class="modal-subtitle">${text}</p><div class="modal-actions"><button class="btn secondary" id="cancel-confirm">Vazgeç</button><button class="btn danger" id="confirm-action">${label}</button></div>`); modal.querySelector('#cancel-confirm')!.addEventListener('click', closeDialog); modal.querySelector<HTMLButtonElement>('#confirm-action')!.addEventListener('click', event => { const button = event.currentTarget as HTMLButtonElement; button.disabled = true; void action(fn).finally(() => { button.disabled = false; }); }); }
function importDialog(): void {
  openDialog('Sunucu yapılandırmasını içe aktar', `<p class="modal-subtitle">Bir sunucu .conf dosyası seçin veya içeriğini yapıştırın. Bu işlem paneldeki mevcut istemci listesini değiştirir.</p><form id="import-form"><label class="file-picker">${icon('upload')}<span>.conf dosyası seç</span><input id="import-file" type="file" accept=".conf,.txt"/></label><label class="textarea-label">Sunucu yapılandırması<textarea name="config" rows="9" spellcheck="false" placeholder="[Interface]&#10;PrivateKey = …&#10;Address = 10.64.0.1/24&#10;ListenPort = 51820" required></textarea></label><label class="checkbox-row"><input type="checkbox" required/><span>Mevcut istemci listesinin değişeceğini anlıyorum.</span></label><div class="modal-note">${icon('shield')}Hook ve komutlar reddedilir. Mevcut istemcilerin özel anahtarları sunucu dosyasında bulunmaz.</div><div class="modal-actions"><button class="btn secondary" type="button" id="import-cancel">Vazgeç</button><button class="btn primary" type="submit">İçe aktar</button></div></form>`, 'wide-modal');
  modal.querySelector('#import-cancel')!.addEventListener('click', closeDialog);
  modal.querySelector<HTMLInputElement>('#import-file')!.addEventListener('change', event => { const file = (event.target as HTMLInputElement).files?.[0]; if (!file) return; void action(async () => { if (file.size > 256 * 1024) throw new Error('Dosya en fazla 256 KB olabilir'); modal.querySelector<HTMLTextAreaElement>('textarea')!.value = await file.text(); }); });
  modal.querySelector<HTMLFormElement>('#import-form')!.addEventListener('submit', event => { event.preventDefault(); const form = event.currentTarget as HTMLFormElement; void submitForm(form, async () => { await api('/api/import', 'POST', { config: new FormData(form).get('config') }); closeDialog(); await refresh(true); toast('Yapılandırma içe aktarıldı'); }); });
}

function renderAuth(): void {
  const setup = session.setupRequired;
  app.innerHTML = `<div class="auth-page"><aside class="auth-story"><div class="auth-wordmark"><img src="/favicon.svg" alt=""/>wireguard simple</div><div><span class="eyebrow">AĞINIZ SİZİN KONTROLÜNÜZDE</span><h1>Sade bir konsol.<br>Güçlü bağlantılar.</h1><p>WireGuard yönetimi, canlı görünürlük ve ihtiyaç duyduğunuz kadar kayıt. Tek, hafif uygulamada.</p><div class="auth-features"><span>${icon('shield')}Bağımsız anahtarlar</span><span>${icon('pulse')}Canlı izleme</span><span>${icon('leaf')}Sınırlı kaynak tüketimi</span></div></div><small>WireGuard Simple · Bağımsız VPN yönetimi</small></aside><section class="auth-form-wrap"><form id="auth-form"><span class="auth-lock">${icon('lock')}</span><div class="eyebrow">${setup ? 'İLK KURULUM' : 'YÖNETİCİ ERİŞİMİ'}</div><h2>${setup ? 'Konsolunuzu hazırlayın.' : 'Tekrar hoş geldiniz.'}</h2><p>${setup ? 'Sunucudaki özel kurulum anahtarıyla ilk yönetici hesabını oluşturun.' : 'Ağınızı yönetmek için oturum açın.'}</p>${setup ? '<label>Kurulum anahtarı<input name="token" type="password" autocomplete="off" required/><small>Sunucunun veri klasöründeki setup-token dosyasında.</small></label>' : ''}<label>Kullanıcı adı<input name="username" autocomplete="username" maxlength="40" required/></label><label>Parola<input name="password" type="password" autocomplete="${setup ? 'new-password' : 'current-password'}" ${setup ? 'minlength="12"' : ''} maxlength="256" required/>${setup ? '<small>En az 12 karakter kullanın.</small>' : ''}</label><button type="submit" class="btn primary full">${setup ? 'Yönetici hesabını oluştur' : 'Oturum aç'}${icon('arrow')}</button><div class="auth-security">${icon('shield')}Erişim yalnızca yönetici hesabınızla sağlanır.</div></form></section></div>`;
  document.querySelector<HTMLFormElement>('#auth-form')!.addEventListener('submit', event => { event.preventDefault(); const form = event.currentTarget as HTMLFormElement; void submitForm(form, async () => { const f = new FormData(form); await api(setup ? '/api/setup' : '/api/login', 'POST', Object.fromEntries(f)); await start(); }); });
}
async function start(): Promise<void> {
  session = await api<Session>('/api/session');
  if (!session.authenticated) { renderAuth(); return; }
  const requested = location.hash.slice(1); if (['overview', 'peers', 'activity', 'storage', 'settings'].includes(requested)) view = requested as View;
  await refresh(true); renderMain(); updateChrome(); clearInterval(poll); poll = setInterval(() => { void refresh(); }, 3000);
}
document.addEventListener('visibilitychange', () => { if (!document.hidden && session?.authenticated) void refresh(); });
document.addEventListener('keydown', event => { if (event.key === '/' && !modal.open && !(document.activeElement instanceof HTMLInputElement || document.activeElement instanceof HTMLTextAreaElement)) { event.preventDefault(); if (view !== 'peers') navigate('peers'); document.querySelector<HTMLInputElement>('#peer-search')?.focus(); } });
window.addEventListener('hashchange', () => { const v = location.hash.slice(1); if (session?.authenticated && ['overview', 'peers', 'activity', 'storage', 'settings'].includes(v) && v !== view) { view = v as View; renderMain(); updateChrome(); } });
void start().catch(error => { app.innerHTML = `<div class="boot"><span class="boot-mark">W</span><h2>Konsola bağlanılamadı</h2><p>${esc(error.message)}</p><button class="btn secondary" id="retry">Yeniden dene</button></div>`; document.querySelector('#retry')!.addEventListener('click', () => location.reload()); });
